def cuped(outcomes,covariates):
    if len(outcomes)!=len(covariates) or not outcomes:
        raise ValueError("aligned_nonempty_inputs_required")
    xm=sum(covariates)/len(covariates)
    ym=sum(outcomes)/len(outcomes)
    var=sum((x-xm)**2 for x in covariates)/len(covariates)
    if var==0: return list(outcomes)
    cov=sum((x-xm)*(y-ym) for x,y in zip(covariates,outcomes))/len(outcomes)
    theta=cov/var
    return [y-theta*(x-xm) for x,y in zip(covariates,outcomes)]

