def bounded_paths(graph,start,target,max_depth=4,max_paths=10):
    queue=[[start]]; found=[]
    while queue and len(found)<max_paths:
        path=queue.pop(0); node=path[-1]
        if node==target:
            found.append(path); continue
        if len(path)-1>=max_depth: continue
        for nxt in sorted(graph.get(node,[])):
            if nxt not in path:
                queue.append(path+[nxt])
    return found

