def compare_systems(candidate,baseline,budget):
    required={"quality","latency_ms","memory_gib","eval_cases"}
    if not required.issubset(candidate) or not required.issubset(baseline):
        return {"comparable":False,"reason":"missing_measurements"}
    violations=[]
    for system,name in ((candidate,"candidate"),(baseline,"baseline")):
        if system["latency_ms"]>budget["max_latency_ms"]: violations.append(name+"_latency")
        if system["memory_gib"]>budget["max_memory_gib"]: violations.append(name+"_memory")
    same_eval=candidate["eval_cases"]==baseline["eval_cases"]
    return {"comparable":same_eval and not violations,"violations":violations,
            "quality_delta":candidate["quality"]-baseline["quality"]}

