def validate_manifest(m):
    required={"code_commit","container_digest","dataset_version","config_digest",
              "seed","hardware","checkpoint_digest","evaluator_version","metrics"}
    missing=sorted(required-set(m))
    errors=["missing_"+x for x in missing]
    if m.get("container_digest") and "@sha256:" not in m["container_digest"]:
        errors.append("container_not_digest_pinned")
    if m.get("seed") is None: errors.append("seed_required")
    return {"valid":not errors,"errors":sorted(set(errors))}

