def join_shadow(control,candidate):
    candidate_by_id={r["request_id"]:r for r in candidate}
    pairs=[]; missing=[]
    for base in control:
        other=candidate_by_id.get(base["request_id"])
        if other is None: missing.append(base["request_id"])
        else: pairs.append({"request_id":base["request_id"],"control":base,"candidate":other})
    return {"pairs":pairs,"missing_candidate_ids":missing,
            "coverage":len(pairs)/len(control) if control else None}

