def promotable_evidence(e,target_bundle,required_slices):
    reasons=[]
    if e.get("bundle_id")!=target_bundle: reasons.append("bundle_mismatch")
    if not e.get("independently_reproduced"): reasons.append("not_reproduced")
    missing=sorted(set(required_slices)-set(e.get("evaluated_slices",[])))
    if missing: reasons.append("missing_slices:"+",".join(missing))
    if not e.get("manifest_valid"): reasons.append("invalid_manifest")
    if e.get("critical_limitation_open"): reasons.append("critical_limitation")
    return {"approved":not reasons,"reasons":reasons}

