def rank_options(options,constraints,weights):
    feasible=[]; rejected=[]
    for option in options:
        reasons=[name for name,required in constraints.items() if required and not option.get(name)]
        if reasons:
            rejected.append({"id":option["id"],"reasons":sorted(reasons)})
            continue
        score=sum(option.get(metric,0)*weight for metric,weight in weights.items())
        feasible.append({"id":option["id"],"score":score})
    feasible.sort(key=lambda x:(-x["score"],x["id"]))
    return {"ranked":feasible,"rejected":rejected}

