def impacted_services(reverse_dependencies,failed,max_nodes=100):
    seen={failed}; queue=[failed]; impacted=[]
    while queue and len(impacted)<max_nodes:
        dependency=queue.pop(0)
        for service in sorted(reverse_dependencies.get(dependency,[])):
            if service not in seen:
                seen.add(service); impacted.append(service); queue.append(service)
                if len(impacted)>=max_nodes: break
    return impacted

