def portfolio_action(metrics,now):
    if any(m["hard_control"] and m["status"]=="failed" for m in metrics):
        return "contain"
    if any(now-m["observed_at"]>m["max_age"] for m in metrics):
        return "investigate"
    strategic=[m for m in metrics if m["category"] in {"outcome","economics","option_risk"}]
    if strategic and sum(m["status"]=="off_target" for m in strategic)>=2:
        return "revisit"
    return "continue"

